class BadHours(ValueError):
    pass

def hours_of(text):
    try:
        n = int(text)
    except ValueError:
        return None
    if n < 0:
        raise BadHours("часы не бывают отрицательными")
    return n

print(hours_of("8"), hours_of("нет"))
try:
    hours_of("-1")
except BadHours as error:
    print(type(error).__name__)

def total_hours(rows):
    if not rows:
        return 0
    return rows[0] + total_hours(rows[1:])

print(total_hours([8, 7, 6]))

def mark(prefix):
    def wrap(fn):
        def inner(*args, **kwargs):
            return prefix + str(fn(*args, **kwargs))
        return inner
    return wrap

@mark("код ")
def show(code, qty=1):
    return code + ":" + str(qty)

print(show("D-1042", qty=3))

